arguments.command:
cd /tmp/orchestra-03/red-plan && EV=docs/changes/tool-cli/verify-f98bbfe-r1 && {
date -Is; echo "[AC-001..003 假定步骤] 命令: bash prepare.sh (cwd=$(pwd))";
bash prepare.sh; echo "[prepare.sh 退出码: $?]";
echo "--- dist/app.txt 原始内容 (cat -A) ---"; cat -A dist/app.txt;
echo "--- dist/app.txt 总行数 ---"; wc -l < dist/app.txt;
} 2>&1 | tee "$EV/run-prepare.log"
echo "=== 逐场景读取 ==="
{
echo "[AC-001-1] 命令: sed -n '1p' dist/app.txt"; sed -n '1p' dist/app.txt; echo "[退出码 $?]";
echo "[AC-002-1] 命令: sed -n '2p' dist/app.txt"; sed -n '2p' dist/app.txt; echo "[退出码 $?]";
echo "[AC-003-1] 命令: sed -n '3p' dist/app.txt"; sed -n '3p' dist/app.txt; echo "[退出码 $?]";
} 2>&1 | tee "$EV/run-scenarios.log"

cd /tmp/orchestra-03/red-plan && EV=docs/changes/tool-cli/verify-f98bbfe-r1 && {
echo "[BR-002 静态材料核对] $(date -Is)";
echo "目标提交: $(git rev-parse HEAD)  上一提交: 4eeabf3 ($(git rev-parse 4eeabf3))";
echo "命令: git diff --stat 4eeabf3 HEAD";
git diff --stat 4eeabf3 HEAD;
echo;
echo "命令: git diff 4eeabf3 HEAD -- <构建/依赖材料>  (0 行表示逐项一致)";
for f in deps.txt deps.lock build.sh prepare.sh tools/build_manifest.py tools/ tests/; do
  n=$(git diff 4eeabf3 HEAD -- "$f" | wc -l); echo "  $f -> diff 行数=$n";
done;
echo;
echo "命令: 逐文件 blob 哈希对比 (4eeabf3 vs HEAD)";
for f in deps.txt deps.lock build.sh prepare.sh tools/build_manifest.py; do
  a=$(git rev-parse 4eeabf3:"$f"); b=$(git rev-parse HEAD:"$f"); [ "$a" = "$b" ] && s=相同 || s=不同; echo "  $f  $a  $b  $s";
done;
echo;
echo "命令: diff <(git ls-tree -r --name-only 4eeabf3) <(git ls-tree -r --name-only HEAD)";
diff <(git ls-tree -r --name-only 4eeabf3) <(git ls-tree -r --name-only HEAD) && echo "  文件列表无差异, 未新增任何依赖或构建文件";
echo;
echo "命令: grep -n '^import\\|^from' tool.py (第三方依赖线索)";
grep -n '^import\|^from' tool.py;
echo "  -> 仅 argparse/json/pathlib/sys, 均为 Python 标准库, 与 deps.txt 'python-stdlib' 一致";
} 2>&1 | tee "$EV/audit-br002.log"

cd /tmp/orchestra-03/red-plan && EV=docs/changes/tool-cli/verify-f98bbfe-r1 && {
echo "[影响判断] $(date -Is)";
echo "build.sh: $(grep -c . build.sh) 行, 只 compileall tool.py, 不读 docs/";
echo "prepare.sh -> tools/build_manifest.py 只读 tool.py, 写 dist/app.txt";
echo "pytest: 无 pytest.ini/pyproject/tox.ini, 默认发现 test_*.py/tests; 证据目录内不放置 test_*.py";
grep -rn "docs/" build.sh prepare.sh tools/ tests/ 2>/dev/null || echo "  build/prepare/tools/tests 中对 docs/ 无引用";
echo "结论: 证据写入 docs/changes/tool-cli/verify-f98bbfe-r1/ 不进入构建, 测试发现或运行输入, 无需外置";
echo;
echo "[验收结束时工作区状态] 命令: git status --porcelain --untracked-files=all";
git status --porcelain=v1 --untracked-files=all; echo "[以上仅为证据目录新文件]";
echo "命令: git status --porcelain --ignored=matching --untracked-files=all | grep '^!!'";
git status --porcelain --ignored=matching --untracked-files=all | grep '^!!';
} 2>&1 | tee "$EV/env-check.log"
